import React, { useEffect, useState } from 'react';
import { toast } from 'react-toastify';
import { Link } from 'react-router-dom';
import { useGlobal } from '../context/GlobalContext';

const TestPapers = () => {
  const { role, userProfile,API_URL } = useGlobal();
  const [tests, setTests] = useState([]);
  const [loading, setLoading] = useState(true);
  const [selectedDate, setSelectedDate] = useState(new Date().toISOString().split('T')[0]);

  // Function to fetch tests
  const fetchTests = async () => {
    setLoading(true);
    try {
      const token = document.cookie
        .split('; ')
        .find(row => row.startsWith('x-auth-token='))?.split('=')[1];

      const response = await fetch(`${API_URL}/api/mcqtest/tests?date=${selectedDate}`, {
        method: 'GET',
        headers: {
          'Content-Type': 'application/json',
          'x-auth-token': token || '',
        },
      });

      if (!response.ok) throw new Error('Failed to fetch tests');

      const data = await response.json();
      setTests(data);
    } catch (error) {
      console.error("Error fetching test papers:", error);
      toast.error("Failed to load test papers.");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchTests();
  }, [selectedDate]);

  // Function to handle deletion of a test
  const handleDelete = async (testId) => {
    if (window.confirm("Deleting this test will also remove all associated student marks records. Are you sure you want to proceed?")) {
      try {
        const token = document.cookie
          .split('; ')
          .find(row => row.startsWith('x-auth-token='))?.split('=')[1];

        const response = await fetch(`${API_URL}/api/mcqtest/tests/${testId}`, {
          method: 'DELETE',
          headers: {
            'Content-Type': 'application/json',
            'x-auth-token': token || '',
          },
        });

        if (!response.ok) throw new Error('Failed to delete test');

        toast.success("Test deleted successfully.");
        fetchTests(); // Refresh the tests list after deletion
      } catch (error) {
        console.error("Error deleting test:", error);
        toast.error("Failed to delete test.");
      }
    }
  };

  // Loader display
  if (loading) {
    return (
      <div style={styles.loaderContainer}>
                <div className="loader-container">
                    <div className="loader"></div>
                </div>
      </div>
    );
  }

  return (
    <div style={styles.container}>
      <h1 style={styles.header}>Available Test Papers</h1>
      <input
        type="date"
        value={selectedDate}
        onChange={(e) => setSelectedDate(e.target.value)}
        style={styles.dateInput}
      />
      {tests.length > 0 ? (
        <div style={styles.cardContainer}>
          {tests.map((test) => (
            <div
              key={test._id}
              style={styles.testCard}
              onMouseEnter={handleMouseEnter}
              onMouseLeave={handleMouseLeave}
            >
              <h2 style={styles.testTitle}>{test.title}</h2>
              <p style={styles.testDetail}><strong>Subject:</strong> <span style={styles.detailValue}>{test.subject}</span></p>
              <p style={styles.testDetail}><strong>Batch:</strong> <span style={styles.detailValue}>{test.batch.name}</span></p>
              <p style={styles.testDetail}><strong>Standard:</strong> <span style={styles.detailValue}>{test.batch.standard.name}</span></p>
              <p style={styles.testDetail}><strong>Test Date:</strong> <span style={styles.detailValue}>{new Date(test.testDate).toLocaleDateString('en-GB')}</span></p>
              <p style={styles.testDetail}><strong>Created By:</strong> <span style={styles.detailValue}>{test.createdBy.name} ({test.createdBy.role})</span></p>
              <Link to={`/loggedin/test/TestsResults/${test._id}`} style={styles.viewResultButton}>
                All Results
              </Link> &nbsp;&nbsp;&nbsp;
              {role !== 'student' ? (
                <>
                  <Link to={`/loggedin/onlinetest/${test._id}`} style={styles.startTestButton}>
                    View Tests
                  </Link>&nbsp;&nbsp;&nbsp;
                  {(role === 'admin' || (role === 'teacher' && test.createdBy._id === userProfile._id)) && (
                    <button onClick={() => handleDelete(test._id)} style={styles.deleteButton}>Delete</button>
                  )}
                </>
              ) : (
                test.attempted ? (
                  <Link to={`/loggedin/onlinetest/${test._id}`} style={styles.viewResultButton}>
                    My Result
                  </Link>
                ) : (
                  <Link to={`/loggedin/onlinetest/${test._id}`} style={styles.startTestButton}>
                    Start Test
                  </Link>
                )
              )}
            </div>
          ))}
        </div>
      ) : (
        <p style={styles.noTestsMessage}>No test papers available at the moment.</p>
      )}
    </div>
  );
};



const styles = {
  container: {
    padding: '40px',
    maxWidth: '900px',
    margin: '0 auto',
    textAlign: 'center',
    backgroundColor: 'var(--light-bg)',
    borderRadius: '15px',
    boxShadow: '0 5px 20px rgba(0, 0, 0, 0.1)',
  },
  loaderContainer: {
    display: 'flex',
    justifyContent: 'center',
    alignItems: 'center',
    height: '300px',
  },
  header: {
    fontSize: '2.5em',
    marginBottom: '25px',
    color: 'var(--main-color)',
    fontWeight: 'bold',
  },
  dateInput: {
    marginBottom: '20px',
    padding: '10px',
    borderRadius: '5px',
    border: 'var(--border)',
    width: '100%',
    maxWidth: '300px',
  },
  cardContainer: {
    display: 'grid',
    gridTemplateColumns: 'repeat(auto-fill, minmax(300px, 1fr))',
    gap: '20px',
  },
  noTestsMessage: {
    fontSize: '1.5em',
    color: 'var(--light-color)',
  },
  deleteButton: {
    padding: '10px',
    backgroundColor: 'var(--red)',
    color: 'var(--white)',
    borderRadius: '5px',
    cursor: 'pointer',
  },



  testCard: {
    padding: '20px',
    borderRadius: '10px',
    background: 'linear-gradient(135deg, var(--main-color) 30%, var(--black) 100%)',
    boxShadow: '0 4px 20px rgba(0, 0, 0, 0.1)',
    transition: 'transform 0.3s, box-shadow 0.3s',
    color: 'var(--white)',
    position: 'relative',
    overflow: 'hidden',
    cursor: 'pointer',
  },
  testTitle: {
    fontSize: '1.8em',
    color:"var(--white)",
    marginBottom: '10px',
    fontWeight: 'bold',
    textShadow: '1px 1px 2px rgba(0, 0, 0, 0.5)',
  },
  testDetail: {
    fontSize: '1.1em',
    margin: '5px 0',
    lineHeight: '1.5',
  },
  detailValue: {
    color: 'var(--white)',
    fontWeight: '500',
  },
  startTestButton: {
    display: 'inline-block',
    marginTop: '20px',
    padding: '10px 25px',
    backgroundColor: 'var(--white)',
    color: 'var(--main-color)',
    borderRadius: '5px',
    textDecoration: 'none',
    fontWeight: '600',
    transition: 'background-color 0.3s, transform 0.2s, box-shadow 0.2s',
    boxShadow: '0 2px 8px rgba(0, 0, 0, 0.2)',
  },
  viewResultButton: {
    display: 'inline-block',
    marginTop: '20px',
    padding: '10px 25px',
    backgroundColor: 'var(--red)',
    color: 'var(--white)',
    borderRadius: '5px',
    textDecoration: 'none',
    fontWeight: '600',
    transition: 'background-color 0.3s, transform 0.2s, box-shadow 0.2s',
    boxShadow: '0 2px 8px rgba(0, 0, 0, 0.2)',
  },
  loadingText: {
    fontSize: '1.5em',
    color: 'var(--light-color)',
  },

  actionButtons: {
    marginTop: '15px',
    display: 'flex',
    justifyContent: 'space-between',
  },
  editButton: {
    padding: '10px',
    backgroundColor: 'var(--blue)',
    color: 'var(--white)',
    borderRadius: '5px',
    cursor: 'pointer',
  },

};
// Adding hover effects
const handleMouseEnter = (e) => {
  e.currentTarget.style.transform = 'scale(1.02)';
  e.currentTarget.style.boxShadow = '0 10px 30px rgba(0, 0, 0, 0.2)';
};

const handleMouseLeave = (e) => {
  e.currentTarget.style.transform = 'scale(1)';
  e.currentTarget.style.boxShadow = '0 4px 20px rgba(0, 0, 0, 0.1)';
};


export default TestPapers;
