import React from 'react';
import { useLocation, Link } from 'react-router-dom';
import logo from './logo.jpg';
import { useGlobal } from "../context/GlobalContext";

const Header = () => {
  const {
    // darkMode, 
    // toggleDarkMode, 
    toggleSidebar
  } = useGlobal();

  const location = useLocation();
  const path = location.pathname;

  // Map paths to readable titles
  const pathTitles = {
    '/': 'Home',
    '/login': 'Login',
    '/loggedin': 'Home',
    '/loggedin/': 'Home',
    '/loggedin/courses': 'Courses',
    '/loggedin/upload/banner/form': 'Upload Banner', 
    '/loggedin/student/attendance': 'Mark Student Attendance',
    '/loggedin/staff/attendance': 'Mark Staff Attendance',
    '/loggedin/student/attendance/:studentId': 'Student Attendance History',
    '/loggedin/staff/attendance/:staffId': 'Staff Attendance History',
    '/loggedin/student/feepayments/:studentId': 'Fee Payment History',
    '/loggedin/students/list': 'Students List',
    '/loggedin/staff/list': 'Staff List',
    '/loggedin/register': 'Register',
    '/loggedin/myprofile': 'My Profile',
    '/loggedin/profile/:id': 'Profile Details',
    '/loggedin/manage-batches/:teacherId': 'Manage Batches',
    '/loggedin/onlinetest/:testid': 'Online MCQ Test',
    '/loggedin/create/onlinemcqtest': 'Create Online MCQ Test',
    '/loggedin/create/offlinetest': 'Create Offline Test',
    '/loggedin/test/mytestslist': 'My Online Tests',
    '/loggedin/test/offline/mytestslist': 'My Offline Tests',
    '/loggedin/test/addStudentmarks/:testId': 'Add Student Marks',
    '/loggedin/test/TestsResults/:testid': 'Test Results',
    '/loggedin/online/fee/payment': 'Online Fee Payment',
    '/loggedin/studymaterial/form': 'Study Material Form',
    '/loggedin/studymaterial/e-book': 'E-Books',
    '/loggedin/studymaterial/Notes': 'Notes',
    '/loggedin/studymaterial/YT-Videos': 'YouTube Videos',
    '/loggedin/studymaterial/Previous-question-papers': 'Previous Question Papers',
    '/comingsoon': 'Coming Soon',
    '/loggedin/quiz': 'Quiz',
    '/loggedin/contact': 'Contact Us',
  };

  // Get title for the current path
  const getTitle = (path) => {
    // Handle dynamic routes
    if (path.includes('/loggedin/student/attendance/')) return 'Student Attendance History';
    if (path.includes('/loggedin/staff/attendance/')) return 'Staff Attendance History';
    if (path.includes('/loggedin/test/addStudentmarks/')) return 'Add Student Marks';
    if (path.includes('/loggedin/test/TestsResults/')) return 'Test Results';
    if (path.includes('/loggedin/profile/')) return 'Profile Details';
    if (path.includes('/loggedin/manage-batches/')) return 'Manage Batches';
    if (path.includes('/loggedin/onlinetest/')) return 'Online MCQ Test';

    // Static paths
    return pathTitles[path] || '';
  };

  return (
    <header className="header">
      <section className="flex">
        <Link to="/loggedin" className="logo">
          <img src={logo} alt="Logo" height={45} />
        </Link>

        <h1 style={{fontSize:'2rem'}}>{getTitle(path)}</h1>

        <div className="icons">
          {/* Hamburger menu */}
          <div id="menu-btn" className="fas fa-bars" onClick={toggleSidebar}></div>

          {/* User profile icon */}
          <Link to="/loggedin/myprofile">
            <div id="user-btn" className="fas fa-user"></div>
          </Link>
        </div>
      </section>
    </header>
  );
};

export default Header;
