import React, { useState } from "react";
import { useGlobal } from "../context/GlobalContext";
import axios from "axios";

const FeePaymentPage = () => {
    const { API_URL, userProfile, setUserProfile } = useGlobal();
    const [paymentDetails, setPaymentDetails] = useState({
        amount: "",
        memo: "",
    });
    const [loading, setLoading] = useState(false);
    const [verifying, setVerifying] = useState(false);
    const [paymentStatus, setPaymentStatus] = useState(null);
    const [errorMessage, setErrorMessage] = useState("");

    // Handle input changes
    const handleInputChange = (e) => {
        const { name, value } = e.target;
        setPaymentDetails({ ...paymentDetails, [name]: value });
    };

    // Handle fee payment
    const handleFeePayment = async () => {
        const pendingFee = userProfile.pendingFee;

        if (!paymentDetails.amount || paymentDetails.amount <= 0) {
            setErrorMessage("Amount must be greater than 0.");
            return;
        }

        // Check if the entered amount exceeds the pending fee
        if (parseFloat(paymentDetails.amount) > pendingFee) {
            setErrorMessage(`The entered amount exceeds your pending fee of ₹${pendingFee}.`);
            return;
        }

        setLoading(true);
        setErrorMessage("");
        setPaymentStatus(null);

        try {
            const token = document.cookie
                .split("; ")
                .find((row) => row.startsWith("x-auth-token="))
                ?.split("=")[1];

            // Step 1: Create Razorpay Order
            const response = await axios.post(
                `${API_URL}/api/online/payment/razorpay/create-order`,
                {
                    studentId: userProfile.id,
                    amount: paymentDetails.amount,
                    currency: "INR",
                    method: "razorpay",
                    memo: paymentDetails.memo,
                },
                { headers: { "x-auth-token": token } }
            );

            const orderData = response.data.order;
            setLoading(false);

            // Step 2: Initialize Razorpay Payment UI
            const options = {
                key: "rzp_live_h26tg64HQMJHSq",
                amount: orderData.amount,
                currency: orderData.currency,
                name: "Fee Payment",
                description: "Payment for course fee",
                order_id: orderData.id,
                handler: async function (response) {
                    setVerifying(true);
                    try {
                        // Step 3: Verify Payment
                        const verifyResponse = await axios.post(
                            `${API_URL}/api/online/payment/razorpay/verify-payment`,
                            {
                                razorpay_order_id: response.razorpay_order_id,
                                razorpay_payment_id: response.razorpay_payment_id,
                                razorpay_signature: response.razorpay_signature,
                            },
                            { headers: { "x-auth-token": token } }
                        );

                        const newPendingFee = userProfile.pendingFee - verifyResponse.data.feePayment.amount;
                        setUserProfile({ ...userProfile, pendingFee: newPendingFee });
                        setPaymentStatus({
                            success: true,
                            data: verifyResponse.data.feePayment,
                        });
                    } catch (error) {
                        setPaymentStatus({
                            success: false,
                            message: error.response?.data?.message || "Payment verification failed.",
                        });
                    } finally {
                        setVerifying(false);
                    }
                },
                prefill: {
                    name: userProfile.name,
                    email: userProfile.email,
                    contact: userProfile.contact,
                },
                theme: {
                    color: "#5a4d91",
                },
            };

            const razorpay = new window.Razorpay(options);
            razorpay.open();
        } catch (error) {
            setErrorMessage(error.response?.data?.message || "Payment failed. Please try again.");
            setLoading(false);
        }
    };

    // Go Back Handler
    const handleGoBack = () => {
        setPaymentStatus(null);
        setPaymentDetails({ amount: "", memo: "" });
        setErrorMessage("");
    };

    return (
        <div className="payment-page-container">
            {loading && <div className="loader-container">
                <div className="loader"></div><br />
                <div className="loading" style={{fontSize:'1.7rem'}}>Initializing Payment...</div>
            </div>}
            {verifying && <div className="loader-container">
                <div className="loader"></div><br />
                <div className="loading">Verifying Payment...</div>
                </div>}

            {!loading && !verifying && !paymentStatus && (
                <div className="payment-form">
                    <h2>Pay Your Fee</h2>
                    {errorMessage && <p className="error-message">{errorMessage}</p>}
                    <p className="pending-fee">Your pending fee: <strong>₹{userProfile.pendingFee}</strong></p>

                    <input
                        type="number"
                        name="amount"
                        placeholder="Enter Amount"
                        value={paymentDetails.amount}
                        onChange={handleInputChange}
                        className="input-field"
                    />
                    <textarea
                        name="memo"
                        placeholder="Add a memo (Optional)"
                        value={paymentDetails.memo}
                        onChange={handleInputChange}
                        className="input-field"
                    />

                    <button onClick={handleFeePayment} className="pay-now-button" disabled={loading}>
                        Pay Now
                    </button>
                </div>
            )}

            {!loading && !verifying && paymentStatus && (
                <div className={`status-screen ${paymentStatus.success ? "success" : "failed"}`}>
                    <h2>{paymentStatus.success ? "Payment Successful!" : "Payment Failed"}</h2>
                    {paymentStatus.success && (
                        <div className="details">
                            <p>Transaction ID: <strong>{paymentStatus.data.transactionId}</strong></p>
                            <p>Amount Paid: <strong>₹{paymentStatus.data.amount}</strong></p>
                            <p>Status: <strong>{paymentStatus.data.status}</strong></p>
                            <p>Payment Method: <strong>{paymentStatus.data.method}</strong></p>
                            <p>Memo: <em>{paymentStatus.data.memo}</em></p>
                        </div>
                    )}
                    {!paymentStatus.success && <p>{paymentStatus.message}</p>}

                    <button onClick={handleGoBack} className="go-back-button">
                        Go Back
                    </button>
                </div>
            )}
        </div>
    );
};

export default FeePaymentPage;
