import React, { useState, useEffect } from 'react';
import axios from 'axios';
import Cookies from 'js-cookie';
import { useGlobal } from "../context/GlobalContext";
import { Link } from 'react-router-dom';
import Slider from "react-slick";
import "slick-carousel/slick/slick.css";
import "slick-carousel/slick/slick-theme.css";
import banner from './banner2.jpg'; // Default banner in case of error or empty banners

const TopScorers = () => {
  const { role, API_URL } = useGlobal();
  const [students, setStudents] = useState([]);
  const [batches, setBatches] = useState([]);
  const [selectedBatch, setSelectedBatch] = useState('');
  const [currentPage, setCurrentPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [loading, setLoading] = useState(false);
  const [banners, setBanners] = useState([]); // To store fetched banners
  const [bannerError, setBannerError] = useState(false); // To track banner fetching errors

  const authToken = Cookies.get('x-auth-token');

  // Fetch Batches
  useEffect(() => {
    const fetchBatches = async () => {
      try {
        const response = await axios.get(`${API_URL}/api/standard/batch`, {
          headers: { 'x-auth-token': authToken },
        });
        setBatches(response.data);
      } catch (error) {
        console.error("Error fetching batches:", error);
      }
    };
    fetchBatches();
  }, [authToken]);

  // Fetch Banners
  useEffect(() => {
    const fetchBanners = async () => {
      try {
        const response = await axios.get(`${API_URL}/api/banners`, {
          headers: { 'x-auth-token': authToken },
        });
        if (response.data.length > 0) {
          setBanners(response.data);
          setBannerError(false); // Reset error state
        } else {
          setBannerError(true); // No banners available
        }
      } catch (error) {
        console.error("Error fetching banners:", error);
        setBannerError(true); // Set error state if the API call fails
      }
    };
    fetchBanners();
  }, [authToken]);

  // Fetch Students (Top Scorers)
  useEffect(() => {
    const fetchStudents = async () => {
      setLoading(true);
      try {
        const response = await axios.get(`${API_URL}/api/users/top-scorers`, {
          headers: { 'x-auth-token': authToken },
          params: { batchId: selectedBatch || undefined, page: currentPage },
        });
        setStudents(response.data.students);
        setTotalPages(response.data.totalPages);
      } catch (error) {
        console.error("Error fetching top scorers:", error);
      } finally {
        setLoading(false);
      }
    };
    fetchStudents();
  }, [selectedBatch, currentPage, authToken]);

  const handleBatchChange = (e) => {
    setSelectedBatch(e.target.value);
    setCurrentPage(1);
  };

  const sliderSettings = {
    dots: true,
    infinite: true,
    speed: 500,
    slidesToShow: 1, // Show 3 images in a single slide
    slidesToScroll: 1, // Scroll one image at a time
    autoplay: true,
    autoplaySpeed: 3000,
    responsive: [
      {
        breakpoint: 1024, // For devices <= 1024px
        settings: {
          slidesToShow: 2, // Show 2 images per slide on medium screens
          slidesToScroll: 1,
        },
      },
      {
        breakpoint: 768, // For devices <= 768px
        settings: {
          slidesToShow: 1, // Show 1 image per slide on smaller screens
          slidesToScroll: 1,
        },
      },
    ],
  };


  return (
    <>
      <div className="top-scorers-container">
        {/* Conditionally render the Image Slider */}
        {!bannerError && banners.length > 0 && (
  <div className="image-slider-container">
    {banners.length === 1 ? (
      <div className="single-banner">
        <img
          src={`${API_URL}${banners[0].image}`}
          alt={banners[0].title}
          className="single-banner-image"
        />
        {/* <div className="single-banner-caption">{banners[0].title}</div> */}
      </div>
    ) : (
      <Slider {...sliderSettings}>
        {banners.map((banner, index) => (
          <div key={index} className="slider-item">
            <img
              src={`${API_URL}${banner.image}`}
              alt={banner.title}
              className="slider-image"
            />
            <div className="slider-caption">{banner.title}</div>
          </div>
        ))}
      </Slider>
    )}
  </div>
)}

        <h2 className="section-heading">Quick Links</h2>
        <div className="quick-links-grid">
          {role !== 'student' ? (
            <Link to="/loggedin/studymaterial/form">
              <div className="link-box" style={{ color: "green" }}>
                <i className="fas fa-book"></i>
                <p>Create Study Material</p>
              </div>
            </Link>
          ) : (
            <Link to="/loggedin/online/fee/payment">
              <div className="link-box" style={{ color: "green" }}>
                <i className="fa-solid fa-indian-rupee-sign"></i>
                <p>Pay Fee</p>
              </div>
            </Link>
          )}
          <Link to="/loggedin/test/mytestslist">
            <div className="link-box" style={{ color: "skyblue" }}>
              <i className="fa-solid fa-globe"></i>
              <p>Online Tests</p>
            </div>
          </Link>
          <Link to="/loggedin/test/offline/mytestslist">
            <div className="link-box" style={{ color: "black" }}>
              <i className="fa-solid fa-school"></i>
              <p>Offline Tests</p>
            </div>
          </Link>
          <Link to="/loggedin/studymaterial/e-book">
            <div className="link-box" style={{ color: "green" }}>
              <i className="fas fa-file-pdf"></i>
              <p>E-Books</p>
            </div>
          </Link>
          <Link to="/loggedin/studymaterial/Notes">
            <div className="link-box" style={{ color: "#cd00ff" }}>
              <i className="fas fa-download"></i>
              <p>PDF Notes</p>
            </div>
          </Link>
          <Link to="/loggedin/studymaterial/YT-Videos">
            <div className="link-box" style={{ color: "red" }}>
              <i className="fas fa-play-circle"></i>
              <p>YouTube Videos</p>
            </div>
          </Link>
          <Link to="/loggedin/studymaterial/Previous-question-papers">
            <div className="link-box" style={{ color: "grey" }}>
              <i className="fas fa-clipboard"></i>
              <p>Previous Papers</p>
            </div>
          </Link>
          <Link to="/loggedin/quiz">
            <div className="link-box" style={{ color: "skyblue" }}>
              <i className="fas fa-question-circle"></i>
              <p>Quiz</p>
            </div>
          </Link>
        </div>
        <hr className="section-divider" />

        <h2 className="section-heading">Top Scoring Students {role === 'student' ? 'From Your Batch' : ''}</h2>
        {role === 'student' ? null : (
          <div className="batch-filter">
            <label htmlFor="batchSelect" className="batch-label">Select Batch: </label>
            <select
              id="batchSelect"
              value={selectedBatch}
              onChange={handleBatchChange}
              className="batch-select"
            >
              <option value="">All Batches</option>
              {batches.map((batch) => (
                <option key={batch._id} value={batch._id}>
                  {batch.name} - {batch.standard.name}
                </option>
              ))}
            </select>
          </div>
        )}

        {loading ? (
          <div className="loader-container">
            <div className="loader"></div>
          </div>
        ) : (
          <div className="table-container">
            <table className="student-table">
              <thead>
                <tr>
                  <th>Student ID</th>
                  <th>Name</th>
                  <th>Batch</th>
                  <th>Score</th>
                </tr>
              </thead>
              <tbody>
                {students.length > 0 ? (
                  students.map((student) => (
                    <tr key={student._id}>
                      <td>{student.studentId}</td>
                      <td>{student.name}</td>
                      <td>{student.batch.name}</td>
                      <td>{student.combinedScore}</td>
                    </tr>
                  ))
                ) : (
                  <tr>
                    <td colSpan="4">No students found</td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        )}

        <div className="pagination-controls">
          <button onClick={() => setCurrentPage((prev) => Math.max(prev - 1, 1))} disabled={currentPage === 1} className="pagination-button">Previous</button>
          <span className="pagination-text">{currentPage} of {totalPages}</span>
          <button onClick={() => setCurrentPage((prev) => Math.min(prev + 1, totalPages))} disabled={currentPage === totalPages} className="pagination-button">Next</button>
        </div>
      </div>
    </>
  );
};

export default TopScorers;
